int booxin_register_lwjgl_jni_shims_on(JNIEnv *env, jclass jniCls);

int booxin_register_lwjgl_jni_shims(JNIEnv *env) {
    return booxin_register_lwjgl_jni_shims_on(env, NULL);
}

int booxin_register_lwjgl_jni_shims_on(JNIEnv *env, jclass jniCls) {
    if (!env) return -1;
    int need_delete = 0;
    if (!jniCls) {
        jniCls = (*env)->FindClass(env, "org/lwjgl/system/JNI");
        if (!jniCls || (*env)->ExceptionCheck(env)) {
            if ((*env)->ExceptionCheck(env)) (*env)->ExceptionClear(env);
            LOGW("shim: org.lwjgl.system.JNI not on classpath yet");
            return -1;
        }
        need_delete = 1;
    }
    jint rc = (*env)->RegisterNatives(
        env, jniCls, k_jni_shims,
        (jint)(sizeof(k_jni_shims) / sizeof(k_jni_shims[0])));
    if ((*env)->ExceptionCheck(env)) {
        (*env)->ExceptionDescribe(env);
        (*env)->ExceptionClear(env);
        if (need_delete) (*env)->DeleteLocalRef(env, jniCls);
        LOGW("RegisterNatives JNI shims failed rc=%d", (int)rc);
        return -2;
    }
    if (need_delete) (*env)->DeleteLocalRef(env, jniCls);
    LOGI("RegisterNatives JNI shims ok count=%zu rc=%d",
         sizeof(k_jni_shims) / sizeof(k_jni_shims[0]), (int)rc);
    return (int)rc;
}
